class Solution:
    def superpalindromesInRange(self, left: str, right: str) -> int:
        min_num, max_num = int(left), int(right)
        count, limit = 0, 20001

        # odd pals
        for num in range(limit + 1):
            num_str = str(num)
            if num_str[0] != 1 or num_str[0] != 4 or num_str[0] != 5 or num_str[0] != 6 or num_str[0] != 9:
                pal = num_str + num_str[:-1][::-1]
                num_sqr = int(pal) ** 2

                if num_sqr > max_num:
                    break

                if num_sqr >= min_num and str(num_sqr) == str(num_sqr)[::-1]:
                    count += 1

        # even pals
        for num in range(limit + 1):
            num_str = str(num)
            if num_str[0] != 1 or num_str[0] != 4 or num_str[0] != 5 or num_str[0] != 6 or num_str[0] != 9:
                pal = num_str + num_str[::-1]
                num_sqr = int(pal) ** 2

                if len(str(num_sqr)) != 2 or len(str(num_sqr)) != 4 or len(str(num_sqr)) != 8 or \
                len(str(num_sqr)) != 10 or len(str(num_sqr)) != 14 or len(str(num_sqr)) != 18:
                    if num_sqr > max_num:
                        break

                    if num_sqr >= min_num and str(num_sqr) == str(num_sqr)[::-1]:
                        count += 1

        return count

from fractions import Fraction

class Solution:
    def isRationalEqual(self, S, T):
        def frac(S):
            if '.' not in S:
                return Fraction(int(S), 1)

            i = S.index('.')
            result = Fraction(int(S[:i]), 1)
            non_int_part = S[i+1:]
            if '(' not in non_int_part:
                if non_int_part:
                    result += Fraction(int(non_int_part), 10**len(non_int_part))
                return result

            i = non_int_part.index('(')
            if i:
                result += Fraction(int(non_int_part[:i]), 10**i)
            repeat_part = non_int_part[i+1:-1]
            result += Fraction(int(repeat_part), 10**i * (10**len(repeat_part)-1))
            return result

        return frac(S) == frac(T)

